// 일반 함수
/**
 *  화면 초기화
 */
scwin.init = function() {

    // 콤보 세팅.
    scwin.setCombo();

    // 기본값 세팅
    scwin.setDefaultVal();
};

/**
 *  콤보박스 만들기
 */
scwin.setCombo = function() {

};

/**
 *  화면의 기본값 세팅
 */
scwin.setDefaultVal = function() {

};

/**
 *  데이터셋 초기화.
 */
scwin.initDs = function() {
    dtl_BefIsuInfoRes.setJSON();
    dtl_AftIsuInfoRes.setJSON();

    txb_ISU_NM.setValue("");
    txb_ISU_ABBRV.setValue("");
    txb_ISU_ENG_NM.setValue("");
    txb_ISU_ENG_ABBRV.setValue("");
    txb_ISUR_CD.setValue("");
    txb_ISUR_NM.setValue("");
};

/**
 * 종목조회
 */
scwin.ins_Search = async function() {
    //데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid("select")) {
        return;
    }

    // Stage2: 중복/사망 executeDynamic 블록 제거 - 정의되지 않은 scwin.sbm_dts_BefIsuInfo_submitdone 와 존재하지 않는 dts_BefIsuInfo 타깃 참조. 아래 정적 $c.sbm.execute 가 실제 조회를 수행한다.

//SCREN_ID=ULDINS20000.gfm
//SCREN_PROCES_TP_CD=01
//method=listGeneralForDynamic
//service=krx.lds.ins.listingcommon.services.ListingCommonApp
//queryId=lds.ins.etc.select.listEtcIsuEditPrcInquiry
//outputMessageId=INS_LIST_ETC_ISU_EDIT_PRC_INQUIRY
//param01=24925
//param02=

    //const sbmComp = $p.getComponentById("sbm_dts_BefIsuInfo");
    //sbmComp.action = "/api/sample/disclosure/select-list";
    //sbmComp.method = "get";
    const reqMap = dma_BefIsuInfoReq.getJSON();    //SCREN_ID=ULDINS20000.gfm  //SCREN_PROCES_TP_CD=01 //param01=24925 //param02=
    const res = await $c.sbm.execute(sbm_dts_BefIsuInfo, reqMap);

    ////ev:submiterror="scwin.dts_BefIsuInfo_OnLoadError" ev:submitdone="scwin.dts_BefIsuInfo_OnLoadCompleted"
    await scwin.dts_BefIsuInfo_OnLoadCompleted(res.responseJSON.body, res.responseJSON.body.length);
};

/**
 * 변경처리
 */
scwin.ins_ChangeProc = async function() {
    // 사전체크
    if (!scwin.chkValid("change")) {
        return;
    }
/*
    if (!confirm("변경하시겠습니까?")) {
        return;
    }
*/

/*
    trs_Save.KeyName = "toinb_dataid4";

	//----W-Craft WebSquare 변환 확인: Post----//
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/EtcInfoAction.do",
        ref : "dts_AftIsuInfo",
        target : "trs_Save=body.content",
        submitDoneHandler : scwin.sbm_trs_Save_submitdone,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);
*/

    const sbmObj = $p.getComponentById("sbm_trs_Save");
    sbmObj.action = "/EtcInfoAction.do?" + "SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + $c.stf.info("SCREN_PROCS_TP_CD_03");
    sbmObj.ref = "data:json,dtl_AftIsuInfoRes";
    let res = {};

    if (await $c.win.confirm("변경하시겠습니까?")) {
        res = await $c.sbm.execute(sbm_trs_Save);
        if (res.responseJSON.success === true) {
            await scwin.trs_Save_OnSuccess();
        } else {
            await scwin.trs_Save_OnFail();
        }         
    }
};

/**
 * 사전체크
 */
scwin.chkValid = function(pGubun) {
    if (pGubun === undefined) {
        return true;
    }
    if (pGubun === "select") {
        if (txb_SRCH_ISUR_CD.getValue() === "") {
            $c.win.alert("발행기관 코드를 입력하세요.");
            txb_SRCH_ISUR_CD.focus();
            return false;
        }
    } else if (pGubun === "batchChange") {
        // 체크된 것이 있는지 검사
        let nTrueCnt = 0;
        for (let nRow = 0; nRow <= dtl_BefIsuInfoRes.getRowCount(); nRow++) {
            if (dtl_BefIsuInfoRes.getCellData(nRow, "CHK") === "T") {
                nTrueCnt++;
                break;
            }
        }
        if (nTrueCnt === 0) {
            $c.win.alert("선택된 종목이 없습니다.");
            return false;
        }
        if (txb_ISUR_CD.getValue() === "") {
            $c.win.alert("발행기관 코드를 입력하세요.");
            txb_ISUR_CD.focus();
            return false;
        }
        if (txb_ISU_NM.getValue() === "") {
            $c.win.alert("기준명을 입력하세요.");
            return false;
        }
    } else if (pGubun === "change") {
        // 처리 대상이 존재 하는지..
        if (dtl_AftIsuInfoRes.getRowCount() < 1) {
            $c.win.alert("처리대상 종목이 존재하지 않습니다.");
            return false;
        }

        // 종목명 체크
        for (let nRow = 0; nRow < dtl_AftIsuInfoRes.getRowCount(); nRow++) {
            if ($c.utils.trim(dtl_AftIsuInfoRes.getCellData(nRow, "ISU_NM")) === "") {
                $c.win.alert("한글기준명을 입력하세요.");
                return false;
            }
            if ($c.utils.trim(dtl_AftIsuInfoRes.getCellData(nRow, "ISU_ABBRV")) === "") {
                $c.win.alert("한글기준약명을 입력하세요.");
                return false;
            }
            if ($c.utils.trim(dtl_AftIsuInfoRes.getCellData(nRow, "ISU_ENG_NM")) === "") {
                $c.win.alert("영문기준명을 입력하세요.");
                return false;
            }
            if ($c.utils.trim(dtl_AftIsuInfoRes.getCellData(nRow, "ISU_ENG_ABBRV")) === "") {
                $c.win.alert("영문기준약명을 입력하세요.");
                return false;
            }
        }
    }
    return true;
};

/**
 * 발생기관 팝업에서 값 받음.
 */
scwin.getParam = function(arrPar) {
    arrPar[0] = txb_param1.getValue(); // 표준코드 OR 발행기관 코드      
    arrPar[1] = txb_param2.getValue();

    return arrPar, length;
};

/**
 * 일괄적용
 */
scwin.batchChange = function() {
    // 일괄적용 사전체크
    if (!scwin.chkValid("batchChange")) {
        return;
    }

    // 헤더정보 복사
    //임시주석 $c.stf.CopyDataSetHeader(dtl_BefIsuInfoRes, dtl_AftIsuInfoRes);

    // row Copy
    //임시주석 scwin.fn_CopyRow();

    let tmpCopyRow = dtl_BefIsuInfoRes.getMatchedJSON("CHK", "T", true, 0, dtl_BefIsuInfoRes.getRowCount() - 1);
    dtl_AftIsuInfoRes.setJSON(tmpCopyRow);
};

/**
 * 데이터셋 RowCopy
 */
scwin.copyRow = function() {
    dtl_AftIsuInfoRes.setBroadcast(false); //grd_AftIsuInfo.ReDraw = false;
    for (let nRow = 0; nRow <= dtl_BefIsuInfoRes.getRowCount(); nRow++) {
        if (dtl_BefIsuInfoRes.getCellData(nRow, "CHK") === "T") {
            dtl_AftIsuInfoRes.insertRow();
            const nLastRow = dtl_AftIsuInfoRes.getRowCount();
            dtl_AftIsuInfoRes.setCellData(nLastRow, "STD_CD", dtl_BefIsuInfoRes.getCellData(nRow, "STD_CD"));
            dtl_AftIsuInfoRes.setCellData(nLastRow, "ISU_NM", txb_ISU_NM.getValue());
            dtl_AftIsuInfoRes.setCellData(nLastRow, "ISU_ABBRV", txb_ISU_ENG_NM.getValue());
            dtl_AftIsuInfoRes.setCellData(nLastRow, "ISU_ENG_NM", txb_ISU_ABBRV.getValue());
            dtl_AftIsuInfoRes.setCellData(nLastRow, "ISU_ENG_ABBRV", txb_ISU_ENG_ABBRV.getValue());
            dtl_AftIsuInfoRes.setCellData(nLastRow, "UNQ_ISU_NM", dtl_BefIsuInfoRes.getCellData(nRow, "UNQ_ISU_NM"));
            dtl_AftIsuInfoRes.setCellData(nLastRow, "UNQ_ISU_ENG_NM", dtl_BefIsuInfoRes.getCellData(nRow, "UNQ_ISU_ENG_NM"));
            dtl_AftIsuInfoRes.setCellData(nLastRow, "LIST_STAT_CD", dtl_BefIsuInfoRes.getCellData(nRow, "LIST_STAT_CD"));
            dtl_AftIsuInfoRes.setCellData(nLastRow, "ACTIV_TP_CD", dtl_BefIsuInfoRes.getCellData(nRow, "ACTIV_TP_CD"));
            dtl_AftIsuInfoRes.setCellData(nLastRow, "KIND", dtl_BefIsuInfoRes.getCellData(nRow, "KIND"));
            dtl_AftIsuInfoRes.setCellData(nLastRow, "ISUR_CD", txb_ISUR_CD.getValue());
            dtl_AftIsuInfoRes.setCellData(nLastRow, "LIST_STAT_NM", dtl_BefIsuInfoRes.getCellData(nRow, "LIST_STAT_NM"));
        }
    }
    dtl_AftIsuInfoRes.setBroadcast(true);     //grd_AftIsuInfo.ReDraw = true;
};

/**
 * 체크가 가능한지 체크
 * 1. 채권은 상장이면 체크 불가
 * 2. 비활성은 체크 불가
 */
scwin.isAbleChk = function(nRow, bCheck) {
    if (bCheck === -1) {
        return;
    }

    // 3 주식워런트 체크(주식워런트 체크 불가)
    if (dtl_BefIsuInfoRes.getCellData(nRow, "KIND") === "주식워런트") {
        $c.win.alert("주식워런트는 변경처리 할 수 없습니다.");
        dtl_BefIsuInfoRes.setCellData(nRow, "CHK", "F");
        return;
    }
    // ETN 체크(ETN 체크 불가)
    if (dtl_BefIsuInfoRes.getCellData(nRow, "KIND") === "ETN") {
        $c.win.alert("ETN은 변경처리 할 수 없습니다.");
        dtl_BefIsuInfoRes.setCellData(nRow, "CHK", "F");
        return;
    }


    // 1. 채권은 상장이면 체크 불가. -> 	모든 상장인경우 변경불가  F-226  2013.11.14
    //var tmpStdCd = dts_BefIsuInfo.NameString(nRow, "STD_CD").substr(0, 3);
    //if( tmpStdCd == "KR1" || tmpStdCd == "KR2" || tmpStdCd == "KR3" || tmpStdCd == "KR6" || tmpStdCd == "KRB"){
    //if( dts_BefIsuInfo.NameString(nRow, "KIND") == "채권" ){		모든 상장인경우 변경불가  F-226  2013.11.14
    if (dtl_BefIsuInfoRes.getCellData(nRow, "LIST_STAT_CD") === "Y") {
        $c.win.alert("상장여부 \"상장\"인 경우 변경처리 할 수 없습니다.");
        dtl_BefIsuInfoRes.setCellData(nRow, "CHK", "F");
        return;
    }
    //}

    // 2. 활성여부 체크(비활성은 체크 불가)
    if (dtl_BefIsuInfoRes.getCellData(nRow, "ACTIV_TP_CD") !== "Y" && dtl_BefIsuInfoRes.getCellData(nRow, "ACTIV_TP_CD") !== "1") {
        $c.win.alert("비활성 종목은 변경처리 할 수 없습니다.");
        dtl_BefIsuInfoRes.setCellData(nRow, "CHK", "F");
        return;
    }
};

/**
 * 전체 체크
 */
scwin.checkAll = function(bCheck) {
    dtl_BefIsuInfoRes.setBroadcast(false); //grd_BefIsuInfo.ReDraw = false;
    for (let nRow = 0; nRow <= dtl_BefIsuInfoRes.getRowCount(); nRow++) {
        if (dtl_BefIsuInfoRes.getCellData(nRow, "LIST_STAT_CD") === "Y") {

        } else if (dtl_BefIsuInfoRes.getCellData(nRow, "ACTIV_TP_CD") !== "Y" && dtl_BefIsuInfoRes.getCellData(nRow, "ACTIV_TP_CD") !== "1") {

        } else {
            if (dtl_BefIsuInfoRes.getCellData(nRow, "KIND") === "주식워런트" || dtl_BefIsuInfoRes.getCellData(nRow, "KIND") === "ETN") {

            } else {
                scwin.check(nRow, bCheck, false);
            }
        }
    }
    dtl_BefIsuInfoRes.setBroadcast(true); //grd_BefIsuInfo.ReDraw = true;
};

/**
 * 전송여부가 N인 경우 체크박스 체크
 */
scwin.check = function(nRow, bCheck, bMsgShow) {
    dtl_BefIsuInfoRes.setCellData(nRow, "CHK", bCheck ? "T" : "F");
};

scwin.grd_BefIsuInfo_CanColumnPosChange = function(row, colid) {
    return true;
};
